// Assemble the final deliverable from all specialist HANDOFF outputs.
// QA-Bot always runs last; its report is included regardless of chain scope.

const orch = $('Orchestrator AI Agent').item.json.output;
const chainScope = Array.isArray(orch.chain_scope) ? orch.chain_scope : [];
const category = orch.request_category || 'UNKNOWN';
const stopPoint = orch.stop_point || 'unknown';

// Safely read each specialist result (may be null if not in scope).
const safeGet = (nodeName, key) => {
  try { return $node[nodeName] ? $node[nodeName].json[key] : null; }
  catch (e) { return null; }
};

const qaResult = $('Call QA-Bot (always last)').item.json;

// Build status table rows.
const specialistNodes = [
  { name: 'Oracle', node: 'Call Oracle' },
  { name: 'Sensei', node: 'Call Sensei' },
  { name: 'Atlas', node: 'Call Atlas' },
  { name: 'JD-Bot', node: 'Call JD-Bot' },
  { name: 'Hunter', node: 'Call Hunter' },
  { name: 'Shakespeare', node: 'Call Shakespeare' },
];
const statusRows = specialistNodes.map(s => {
  const inScope = chainScope.includes(s.name);
  return { specialist: s.name, status: inScope ? 'executed' : 'not_in_scope' };
});
statusRows.push({ specialist: 'QA-Bot', status: 'executed (always)' });

return [{
  json: {
    request_category: category,
    chain_scope: chainScope,
    stop_point: stopPoint,
    routing_rationale: orch.routing_rationale || '',
    status_table: statusRows,
    qa_report: qaResult || {},
    assembled_at: new Date().toISOString(),
    note: 'Full deliverable: inspect each Call <Specialist> node output for specialist assets and HANDOFF blocks.',
  }
}];
